def normalize(source: str) -> str:
    return textwrap.dedent(source).lstrip()

def write_exact(path: Path, source: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_suffix(path.suffix + ".tmp")
    temporary.write_text(normalize(source), encoding="utf-8", newline="\n")
    os.replace(temporary, path)

def find_all_bounds(source: str) -> tuple[int, int]:
    marker = "__all__ = ["
    start = source.find(marker)
    if start == -1:
        raise RuntimeError("UMD package __all__ list is missing")
    opening = source.find("[", start)
    cursor, depth, in_string, quote, escaped = opening, 0, False, "", False
    while cursor < len(source):
        character = source[cursor]
        if in_string:
            if escaped:
                escaped = False
            elif character == "\\":
                escaped = True
            elif character == quote:
                in_string = False
        else:
            if character in ("'", '"'):
                in_string, quote = True, character
            elif character == "[":
                depth += 1
            elif character == "]":
                depth -= 1
                if depth == 0:
                    return opening, cursor
        cursor += 1
    raise RuntimeError("UMD package __all__ closing bracket is missing")

def update_init() -> None:
    source = INIT.read_text(encoding="utf-8")
    marker = "from .certified_active_canonical_market_registry_query_session_read_model_admission_ledger_read_model_admission_ledger_read_model_admission_gate import ("
    if marker not in source:
        source = source.rstrip() + "\n\n" + normalize(INIT_IMPORT)
    opening, closing = find_all_bounds(source)
    block = source[opening + 1:closing]
    missing = [name for name in EXPORTED_NAMES if f'"{name}"' not in block and f"'{name}'" not in block]
    if missing:
        insertion = "".join(f'    "{name}",\n' for name in missing)
        source = source[:closing] + insertion + source[closing:]
    compile(source, str(INIT), "exec")
    write_exact(INIT, source)

def verify_upstream() -> None:
    sys.path.insert(0, str(ROOT))
    try:
        for module_name, verifier_name in UPSTREAM_MODULES:
            module = importlib.import_module("qseries_v2.universal_market_discovery." + module_name)
            verifier = getattr(module, verifier_name, None)
            if verifier is None:
                raise RuntimeError(f"Certified upstream verifier missing: {module_name}.{verifier_name}")
            if verifier() is not True:
                raise RuntimeError(f"Certified upstream verification failed: {module_name}")
    finally:
        if str(ROOT) in sys.path:
            sys.path.remove(str(ROOT))

def verify_current() -> None:
    sys.path.insert(0, str(ROOT))
    try:
        importlib.invalidate_caches()
        module = importlib.import_module(
            "qseries_v2.universal_market_discovery."
            "certified_active_canonical_market_registry_query_session_read_model_admission_ledger_read_model_admission_ledger_read_model_admission_gate"
        )
        missing = [name for name in EXPORTED_NAMES if not hasattr(module, name)]
        if missing:
            raise RuntimeError("UMD-038 missing symbols: " + ", ".join(missing))
        if module.verify_umd_038_certified_active_canonical_market_registry_query_session_read_model_admission_ledger_read_model_admission_ledger_read_model_admission_gate() is not True:
            raise RuntimeError("UMD-038 verification returned false")
    finally:
        if str(ROOT) in sys.path:
            sys.path.remove(str(ROOT))

def sha256_file(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()

